const payload = $input.first().json;
const orderId = payload.payment?.order_id || payload.order_id || 'N/A';
const amount = payload.payment?.amount_in_cents ? (payload.payment.amount_in_cents / 100) : (payload.amount || 0);
const eventType = payload.event_type || 'unknown';
const status = payload.payment?.status || 'unknown';
const transactionId = payload.payment?.transaction_id || 'N/A';
const customerName = payload.customer?.name || payload.customer_name || 'Cliente';
const customerPhone = payload.customer?.phone || payload.customer_phone || '';
const customerEmail = payload.customer?.email || payload.customer_email || '';
const paymentMethod = payload.payment?.payment_method || payload.payment_method || 'N/A';

const metodoPago = {
  'card': 'Tarjeta',
  'pse': 'PSE',
  'nequi': 'Nequi',
  'daviplata': 'Daviplata',
  'cash': 'Efectivo'
} [paymentMethod] || paymentMethod;

let mensajeEstado = '';
let esPagoAprobado = false;

switch(eventType) {
  case 'payment.approved':
    mensajeEstado = '✅ PAGO APROBADO';
    esPagoAprobado = true;
    break;
  case 'payment.rejected':
    mensajeEstado = '❌ PAGO RECHAZADO';
    break;
  case 'void.approved':
    mensajeEstado = '💸 REEMBOLSO APROBADO';
    break;
  default:
    mensajeEstado = '📋 Estado: ' + status;
}

return {
  orderId,
  amount,
  eventType,
  status,
  transactionId,
  customerName,
  customerPhone,
  customerEmail,
  paymentMethod: metodoPago,
  mensajeEstado,
  esPagoAprobado,
  timestamp: new Date().toISOString()
};
